-- GOZA Fichaje: ejecutar únicamente en un proyecto Supabase NUEVO y exclusivo.
create table public.staff(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id),employee_number text unique not null,full_name text not null,role text not null default 'employee' check(role in ('employee','admin')),active boolean not null default true,created_at timestamptz not null default now());
create table public.shifts(id uuid primary key default gen_random_uuid(),staff_id uuid not null references public.staff(id),started_at timestamptz not null default now(),ended_at timestamptz,pause_started_at timestamptz,pause_seconds integer not null default 0 check(pause_seconds>=0),check(ended_at is null or ended_at>=started_at));
create unique index only_one_open_shift on public.shifts(staff_id) where ended_at is null;
create index shifts_started_idx on public.shifts(started_at desc);
create table public.incidents(id uuid primary key default gen_random_uuid(),staff_id uuid not null references public.staff(id),created_by uuid not null references public.staff(id),created_at timestamptz not null default now(),reason text not null);
create table public.clock_events(id uuid primary key default gen_random_uuid(),shift_id uuid not null references public.shifts(id),staff_id uuid not null references public.staff(id),event_type text not null check(event_type in ('in','out','pause_start','pause_end')),happened_at timestamptz not null default now());
create index clock_events_idx on public.clock_events(staff_id,happened_at desc);
alter table public.staff enable row level security;
alter table public.shifts enable row level security;
alter table public.incidents enable row level security;
alter table public.clock_events enable row level security;
revoke all on public.staff,public.shifts,public.incidents,public.clock_events from anon,authenticated;
create policy staff_self_read on public.staff for select to authenticated using(user_id=(select auth.uid()));
grant select on public.staff to authenticated;
create function public.my_staff_id() returns uuid language sql stable security definer set search_path='' as $$ select id from public.staff where user_id=(select auth.uid()) and active=true limit 1 $$;
create function public.is_goza_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.staff where user_id=(select auth.uid()) and role='admin' and active=true) $$;
create function public.my_shifts() returns setof public.shifts language plpgsql stable security definer set search_path='' as $$begin if public.my_staff_id() is null then raise exception 'Acceso denegado';end if;return query select * from public.shifts where staff_id=public.my_staff_id() order by started_at desc limit 120;end$$;
create function public.admin_staff() returns setof public.staff language plpgsql stable security definer set search_path='' as $$begin if not public.is_goza_admin() then raise exception 'Acceso denegado';end if;return query select * from public.staff order by full_name;end$$;
create function public.admin_shifts(p_from timestamptz,p_to timestamptz) returns table(id uuid,staff_id uuid,started_at timestamptz,ended_at timestamptz,pause_started_at timestamptz,pause_seconds integer,employee_number text,full_name text) language plpgsql stable security definer set search_path='' as $$begin if not public.is_goza_admin() then raise exception 'Acceso denegado';end if;if p_to<=p_from or p_to-p_from>interval '370 days' then raise exception 'Periodo inválido';end if;return query select s.id,s.staff_id,s.started_at,s.ended_at,s.pause_started_at,s.pause_seconds,e.employee_number,e.full_name from public.shifts s join public.staff e on e.id=s.staff_id where s.started_at>=p_from and s.started_at<=p_to order by s.started_at desc limit 20000;end$$;
create function public.admin_add_staff(p_user_id uuid,p_number text,p_name text,p_role text default 'employee') returns void language plpgsql security definer set search_path='' as $$begin if not public.is_goza_admin() then raise exception 'Acceso denegado';end if;if p_role not in ('employee','admin') then raise exception 'Rol no válido';end if;insert into public.staff(user_id,employee_number,full_name,role) values(p_user_id,trim(p_number),trim(p_name),p_role);end$$;
create function public.clock_in() returns void language plpgsql security definer set search_path='' as $$declare sid uuid; shiftid uuid;begin sid:=public.my_staff_id();if sid is null then raise exception 'Cuenta no autorizada';end if;insert into public.shifts(staff_id) values(sid) returning id into shiftid;insert into public.clock_events(shift_id,staff_id,event_type) values(shiftid,sid,'in');end$$;
create function public.pause_start() returns void language plpgsql security definer set search_path='' as $$declare sid uuid; shiftid uuid;begin sid:=public.my_staff_id();if sid is null then raise exception 'Cuenta no autorizada';end if;update public.shifts set pause_started_at=now() where staff_id=sid and ended_at is null and pause_started_at is null returning id into shiftid;if shiftid is null then raise exception 'No hay jornada abierta o ya hay una pausa';end if;insert into public.clock_events(shift_id,staff_id,event_type) values(shiftid,sid,'pause_start');end$$;
create function public.pause_end() returns void language plpgsql security definer set search_path='' as $$declare sid uuid; shiftid uuid;begin sid:=public.my_staff_id();if sid is null then raise exception 'Cuenta no autorizada';end if;update public.shifts set pause_seconds=pause_seconds+greatest(0,extract(epoch from(now()-pause_started_at))::integer),pause_started_at=null where staff_id=sid and ended_at is null and pause_started_at is not null returning id into shiftid;if shiftid is null then raise exception 'No hay pausa activa';end if;insert into public.clock_events(shift_id,staff_id,event_type) values(shiftid,sid,'pause_end');end$$;
create function public.clock_out() returns void language plpgsql security definer set search_path='' as $$declare sid uuid;shiftid uuid;begin sid:=public.my_staff_id();if sid is null then raise exception 'Cuenta no autorizada';end if;update public.shifts set ended_at=now(),pause_seconds=pause_seconds+case when pause_started_at is null then 0 else greatest(0,extract(epoch from(now()-pause_started_at))::integer) end,pause_started_at=null where staff_id=sid and ended_at is null returning id into shiftid;if shiftid is null then raise exception 'No hay jornada abierta';end if;insert into public.clock_events(shift_id,staff_id,event_type) values(shiftid,sid,'out');end$$;
revoke execute on function public.my_staff_id(),public.is_goza_admin(),public.my_shifts(),public.admin_staff(),public.admin_shifts(timestamptz,timestamptz),public.admin_add_staff(uuid,text,text,text),public.clock_in(),public.clock_out(),public.pause_start(),public.pause_end() from public,anon;
grant execute on function public.my_staff_id(),public.is_goza_admin(),public.my_shifts(),public.admin_staff(),public.admin_shifts(timestamptz,timestamptz),public.admin_add_staff(uuid,text,text,text),public.clock_in(),public.clock_out(),public.pause_start(),public.pause_end() to authenticated;
